using System.Collections.Generic;

/// <summary>Hero narratives keyed by stable ID.</summary>
public static class HeroStory
{
    private static readonly Dictionary<string, (string Opening, string Ending)> Stories = new()
    {
        ["d3dd9f4baffd29e43bf87ab29437b30f"] = ("Avery has studied magic since childhood, but books can only teach so much. The dungeons offer a chance to discover wonders firsthand, alongside companions brave enough to explore them.", "Avery returns with stories and discoveries no book could have supplied. The dungeons have deepened a lifelong love of magic, and the journey has given Avery friends to share it with."),
        ["173b3bf3552315a408b274b2cb9f7cbe"] = ("Morgan grew up admiring martial skill and dreams of becoming a champion in their own right. With a party at their side, they set out to face the strongest challenges the dungeons can offer.", "Morgan has overcome the dungeons' greatest challenges and earned a story worth telling back home. The victories belong to the whole party, and Morgan wears that achievement proudly."),
        ["5495724c2afa1734eb3b4c7657a3af34"] = ("Rowan learned to survive by staying a step ahead. Now they want something more than survival: a legendary adventure and a fortune earned on their own terms.", "Rowan returns with treasure and a tale few would believe. For once, the best part of getting ahead was bringing the whole party along."),
        ["c0c955fd7e95ab24e836ec40e4ceb8b2"] = ("Quinn has spent years studying ancient knowledge and wants to see the places that inspired those old accounts. The dungeons promise discoveries no library can hold.", "Quinn returns with firsthand knowledge and more questions than ever. The journey has made the old stories richer—and given Quinn a story of their own."),
        ["72cc990e9ae0c9849a631719a2431227"] = ("Raised among wanderers, Alex has always wanted to see what lies beyond the next horizon. The dungeons are the next great challenge, and Alex hopes to meet companions who share that curiosity.", "Alex has traveled farther and faced greater dangers than they once imagined. New friends and memories make this journey one worth carrying onward."),
        ["b94c6bed23a28be499beb9a7aacffe06"] = ("Jordan has collected stories from travelers for years. Now they want to live an adventure worth telling, starting with the dungeons and the companions they meet along the way.", "Jordan returns with a tale of monsters, close calls, and friends who stood together. It is their favorite story yet, and they were there for every word."),
        ["f856c5228c5189d45891d5e429791694"] = ("Riley feels most at home in the natural world, but curiosity draws them toward the strange places beneath it. They set out to explore the dungeons and learn what lives there.", "Riley returns with a greater understanding of the world beyond familiar paths. The journey has shown them that companionship can flourish in unexpected places, too."),
        ["485a983a93bc5974c91c4599e8cfecd6"] = ("Casey loves solving problems and wants to put their ingenuity to the test. A dungeon full of unknown dangers is just the challenge, especially with a capable party to tackle it together.", "Casey has faced problems no workshop could have prepared them for. With help from their companions, they found a way through—and came home eager for the next challenge."),
        ["41c5a0bf98e7d0246add0078566dfb23"] = ("Taylor believes people can achieve more when they work together. They set out to assemble a party and prove that trust can carry it through even the most dangerous dungeons.", "Taylor's party has conquered challenges none of them could have faced alone. Their achievement is proof of the trust they built along the way."),
        ["47f27c89d15496d488b89528fcc5c970"] = ("Jamie is drawn to challenges that demand both courage and a good plan. They set out to lead a party through the dungeons and see how far their judgment can take them.", "Jamie's plans were tested at every turn, and the party overcame each challenge together. The final victory is one they all earned."),
        ["355be7c629ed2c54bb20a558c41b1d5d"] = ("Skylar has spent their travels helping people in need. They now hope to grow stronger in the dungeons, so they can be there for others when the road becomes dangerous.", "Skylar returns stronger and with companions who helped carry the burden. Together they faced the dungeons and brought one another safely home."),
        ["177de5b2cdf7c5d45bed8ebb5519327e"] = ("Dakota knows how to follow a trail through the wild, but the dungeons offer paths no tracker can predict. They set out to see where those paths lead, with a party at their side.", "Dakota followed the trail all the way through the deepest challenges. The journey was difficult, but the companions who shared it made every step worthwhile."),
        ["73b36038ad20f3147ae7c1d7e2377d08"] = ("Sage knows many old mysteries, yet the dungeons still hold questions worth pursuing. They gather companions and set out to learn what experience alone can teach.", "Even Sage found surprises in the depths. The journey added new memories to old knowledge, and new friends to share them with."),
        ["f771be67989ed494b9bd8afc86f42824"] = ("Cameron has spent years exploring the possibilities of illusion. They are eager to test their creativity against the unexpected challenges waiting in the dungeons.", "Cameron discovered that the dungeons could surprise even an illusionist. With their companions, they turned uncertainty into an adventure worth remembering."),
        ["2904ad47018b4a346af5daccce458f5c"] = ("Finley loves a challenge that rewards a quick mind. The dungeons sound too tempting to resist, and a few good companions might make the adventure even more fun.", "Finley has outwitted dangers that once seemed impossible. The best part was having friends along to see it happen."),
        ["b0d62fc7388488a40b0b07dc00ee8768"] = ("Harper has always found inspiration in music and the people around them. They set out with a party to experience an adventure that might inspire their greatest melody yet.", "Harper returns with memories of courage, friendship, and hard-won victories. There is more than enough inspiration now for a melody to remember them by."),
        ["adf833241425af5438a45f42a0b50d0d"] = ("Reese knows the care and effort that go into making dependable equipment. Now they want to venture beyond the forge, face the dungeons, and see what strength they can build alongside a party.", "Reese has faced the challenges of the depths and earned the trust of their companions. The journey has given them a new kind of strength to carry home."),
        ["a1a66819d0b73094f845c71c40b5208a"] = ("Logan has fought for crowds before, but now wants to fight for something better. They set out to conquer the dungeons with companions they can stand beside and protect.", "Logan returns from the dungeons with victories shared among friends. This time, the fights meant something beyond the cheers."),
        ["7b41db0a4e891c24093789f3ff6a8c65"] = ("Kai has devoted themself to discipline and self-improvement. The dungeons offer a chance to test that resolve and learn from the companions who join the journey.", "Kai has faced the dungeons' hardest trials and grown through each one. The journey taught them as much about trusting others as it did about their own strength."),
        ["5aeb231ec594b13458da991976aeedde"] = ("Sydney grew up delighting crowds in a traveling circus, but now dreams of a bigger adventure. The dungeons promise danger, discovery, and a chance to find a new troupe of companions.", "Sydney has completed a feat greater than any performance they once imagined. The adventure is over, but the memories made with their new companions will last."),
        ["066579380a2cc5d479da8424adabfea7"] = ("Blake loves experimenting and wants to discover what the wider world can teach them. The dungeons offer the perfect reason to venture out and share the journey with a party.", "Blake returns with new ideas and experiences no experiment at home could provide. Their companions helped make every discovery possible."),
        ["cbef25a4db7dbee41bd2ab6e4cb5fe48"] = ("Charlie has long cared about protecting ancient relics. They set out to explore the dungeons, hoping to better understand the dangers and wonders hidden within.", "Charlie returns with a deeper respect for the past and the dangers surrounding it. Their companions helped them face those dangers and make it home."),
        ["ce1a8d7760520a046bc6dd1813244da7"] = ("Taylor honed their skills in the forest and wants to see how far those skills can take them. The dungeons offer a challenge unlike any they have faced, and a party to face it with.", "Taylor has traveled beyond familiar woods and overcome the deepest challenges with their companions. They return with confidence earned through every step of the journey."),
        ["cd1892de4263374498332f1cec37465a"] = ("Alex enjoys bringing different people together and wants to build a party capable of something extraordinary. Conquering the dungeons seems like a fine place to begin.", "Alex's companions came from different paths, but together they reached the end of the adventure. What they achieved as a party is a story Alex will always be proud to tell."),
    };

    public static string Opening(string id) =>
        id != null && Stories.TryGetValue(id, out var story) ? story.Opening : null;
    public static string Ending(string id) =>
        id != null && Stories.TryGetValue(id, out var story) ? story.Ending : null;
}
